import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"种族设定","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/index.md","filePath":"表层/种族/index.md","lastUpdated":1787066340000}'),h={name:"表层/种族/index.md"};function t(o,a,n,d,f,u){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="种族设定" tabindex="-1">种族设定 <a class="header-anchor" href="#种族设定" aria-label="Permalink to &quot;种族设定&quot;">​</a></h1><h2 id="概念诠释" tabindex="-1">概念诠释 <a class="header-anchor" href="#概念诠释" aria-label="Permalink to &quot;概念诠释&quot;">​</a></h2><p>种族设定部分描述神造物世界中各智慧种族的生理特征、社会特性、历史沿革与当代地位。</p><h2 id="种族分类" tabindex="-1">种族分类 <a class="header-anchor" href="#种族分类" aria-label="Permalink to &quot;种族分类&quot;">​</a></h2><h3 id="三大主族" tabindex="-1">三大主族 <a class="header-anchor" href="#三大主族" aria-label="Permalink to &quot;三大主族&quot;">​</a></h3><p>当前世界舞台上最重要的三个种族，作为世界三极，对世界格局起着根本性影响。</p><ul><li><a href="./鹿族">鹿族</a> —— 冷战一极</li><li><a href="./熊族">熊族</a> —— 冷战一极</li><li><a href="./狼族">狼族</a> —— 新兴一极</li></ul><h3 id="五大主族-共同体时代" tabindex="-1">五大主族（共同体时代） <a class="header-anchor" href="#五大主族-共同体时代" aria-label="Permalink to &quot;五大主族（共同体时代）&quot;">​</a></h3><p>共同体时期最重要的五个种族，分别承担农业、科研、政治、工业与军事分工，各自代表共同体旗帜上五星的一角。</p><ul><li><a href="./牛族">牛族</a> —— 农业担当</li><li><a href="./鹿族">鹿族</a> —— 科研担当</li><li><a href="./鹤族">鹤族</a> —— 政治担当</li><li><a href="./熊族">熊族</a> —— 工业担当</li><li><a href="./甲族">甲族</a> —— 军事担当</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./五大主族总览">五大主族总览</a></p></blockquote><h3 id="新兴种族" tabindex="-1">新兴种族 <a class="header-anchor" href="#新兴种族" aria-label="Permalink to &quot;新兴种族&quot;">​</a></h3><p>黑暗时代起陆续出现或崛起、进入大陆视野的种族。</p><ul><li><a href="./狼族">狼族</a></li><li><a href="./狐族">狐族</a></li><li><a href="./兔族">兔族</a></li><li><a href="./鸽族">鸽族</a></li><li><a href="./鹰族">鹰族</a></li><li><a href="./蜥族">蜥族</a></li></ul><h3 id="传说种" tabindex="-1">传说种 <a class="header-anchor" href="#传说种" aria-label="Permalink to &quot;传说种&quot;">​</a></h3><p>仅存在于古代文献与目击传闻之中、是否存世尚不确定的种族。</p><ul><li><a href="./龙族">龙族</a></li><li><a href="./猫族">猫族</a></li><li><a href="./焰种">焰种</a></li></ul><h3 id="独立种族" tabindex="-1">独立种族 <a class="header-anchor" href="#独立种族" aria-label="Permalink to &quot;独立种族&quot;">​</a></h3><ul><li><a href="./精灵族">精灵族</a></li></ul><h3 id="已亡种族" tabindex="-1">已亡种族 <a class="header-anchor" href="#已亡种族" aria-label="Permalink to &quot;已亡种族&quot;">​</a></h3><p>猪族、蝠族、鼠族、虎族、豹族——均已在历史中彻底消亡。其中猪、虎、豹、蝠四族在黑暗时代被狼族少年灭绝，鼠族亦已消亡。</p><blockquote><p>新五族（猪、蝠、豹、虎、鹰）为黑暗时代的统治种族，现仅存鹰族。</p></blockquote><h3 id="流亡-丧失主权的种族" tabindex="-1">流亡/丧失主权的种族 <a class="header-anchor" href="#流亡-丧失主权的种族" aria-label="Permalink to &quot;流亡/丧失主权的种族&quot;">​</a></h3><p>牛族、羊族——或因迁徙而流亡，或已丧失主权。牛族见 <a href="./牛族">牛族</a>，羊族暂无独立条目。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./五大主族总览">五大主族总览</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li></ul><hr>',28)])])}const p=e(h,[["render",t]]);export{c as __pageData,p as default};
